<script setup lang="ts">
import Select from 'primevue/select'
import type { AcademicYear, GradeLevel, SchoolClass, Semester } from '@/types/academic'
const props = withDefaults(defineProps<{ academicYears?: AcademicYear[]; grades?: GradeLevel[]; classes?: SchoolClass[]; semesters?: Semester[]; academicYearId?: number | null; gradeId?: number | null; classId?: number | null; semesterId?: number | null; loading?: boolean }>(), { academicYears: () => [], grades: () => [], classes: () => [], semesters: () => [], academicYearId: null, gradeId: null, classId: null, semesterId: null, loading: false })
const emit = defineEmits<{ 'update:academicYearId': [value: number | null]; 'update:gradeId': [value: number | null]; 'update:classId': [value: number | null]; 'update:semesterId': [value: number | null] }>()
</script>
<template><section class="content-surface assignment-context-panel"><div class="section-heading"><div><h2>Context phân công</h2><p class="section-caption">Chọn năm học, khối, lớp và học kỳ để xem dữ liệu.</p></div></div><div class="catalog-context-form"><div class="field-group"><label for="assignment-year">Năm học</label><Select id="assignment-year" :model-value="props.academicYearId" :options="props.academicYears" option-label="code" option-value="id" placeholder="Chọn năm học" :loading="props.loading" fluid @update:model-value="emit('update:academicYearId', $event)" /></div><div class="field-group"><label for="assignment-grade">Khối</label><Select id="assignment-grade" :model-value="props.gradeId" :options="props.grades" option-label="name" option-value="id" :disabled="!props.academicYearId" fluid @update:model-value="emit('update:gradeId', $event)" /></div><div class="field-group"><label for="assignment-class">Lớp</label><Select id="assignment-class" :model-value="props.classId" :options="props.classes" option-label="classCode" option-value="id" :disabled="!props.academicYearId" fluid @update:model-value="emit('update:classId', $event)" /></div><div class="field-group"><label for="assignment-semester">Học kỳ</label><Select id="assignment-semester" :model-value="props.semesterId" :options="props.semesters" option-label="name" option-value="id" :disabled="!props.academicYearId" fluid @update:model-value="emit('update:semesterId', $event)" /></div></div></section></template>
